#!/usr/bin/env node

import { randomUUID } from "node:crypto";
import { rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { parseArgs } from "node:util";
import { experimental_generateTypes, experimental_readRawConfig } from "wrangler";

const ENV_INTERFACE = "CloudflareEnv";
const HEADER =
	"// Generated by scripts/cloudflare-typegen.mjs from wrangler.jsonc. Run `npm run typegen:cloudflare` after changing bindings.";

const { values } = parseArgs({
	args: process.argv.slice(2),
	options: {
		config: { type: "string", default: "wrangler.jsonc" },
		output: { type: "string", default: "cloudflare-env.d.ts" },
	},
});
const configPath = resolve(values.config);
const outputPath = resolve(values.output);

const { rawConfig } = experimental_readRawConfig({ config: configPath });
const { main: _entrypoint, ...bindingsOnlyConfig } = rawConfig;
const tempConfigPath = join(dirname(configPath), `.wrangler-typegen-${randomUUID()}.jsonc`);
writeFileSync(tempConfigPath, JSON.stringify(bindingsOnlyConfig));

let generated;
try {
	generated = await experimental_generateTypes({
		config: tempConfigPath,
		envInterface: ENV_INTERFACE,
		includeEnv: true,
		includeRuntime: false,
		strictVars: true,
		path: outputPath,
	});
} finally {
	rmSync(tempConfigPath, { force: true });
}

if (generated.env === null) {
	console.error(`cloudflare-typegen: no environment types were generated from ${configPath}`);
	process.exit(1);
}

writeFileSync(outputPath, `${HEADER}\n${generated.env.trimEnd()}\n`);
console.log(`Wrote ${outputPath}`);
